// Support header for the C++ code generated by tools/bb2cpp from BlitzBasic.
//
// Declares the runtime (basic.h intrinsics + bbapi.h commands) and the helpers that reproduce the exact
// semantics of the original x86 code generator. See Docs/ARCHITECTURE.md "Transpiler".
#ifndef BBCPP_H
#define BBCPP_H

#include <cstdint>
#include <cmath>
#include <climits>
#include <cstring>

#include "basic.h"
#include "bbapi.h"
#include "userlibs.h"
#include "../gxruntime/wiiu_prof.h"

// intrinsics not declared in basic.h
int _bbObjEachFirst2( BBObj **var,BBObjType *type );
int _bbObjEachNext2( BBObj **var );

// custom type descriptor with N field types : same layout as BBObjType (basic.h), which declares fieldTypes[1]
#pragma pack( push,1 )
template<int N> struct BBObjTypeN{
	int type;					// BBTYPE_OBJ (5)
	BBObj used,free;			// list heads
	int fieldCnt;
	BBType *fieldTypes[N];
};
// Blitz array (vector) type : same layout as BBVecType
struct BBVecTypeS{
	int type;					// BBTYPE_VEC (6)
	int size;
	BBType *elementType;
};
// Dim array with N dimensions : same layout as BBArray, which declares scales[1]
template<int N> struct BBArrayN{
	void *data;
	int elementType,dims;
	int scales[N];
};
#pragma pack( pop )

// float -> int : x87 fistp, round to nearest even; out of range / NaN gives 0x80000000
static inline int bbFloatToInt( float f ){
	if( !(f>=-2147483648.0f && f<2147483648.0f) ) return INT_MIN;
	return (int)lrintf( f );
}

// x86 masks shift counts to 5 bits
static inline int bbShl( int a,int b ){ return (int)((unsigned)a<<(b&31)); }
static inline int bbShr( int a,int b ){ return (int)((unsigned)a>>(b&31)); }
static inline int bbSar( int a,int b ){ return a>>(b&31); }

// integer division : x86 idiv traps on 0 and INT_MIN/-1; here they give 0 / INT_MIN instead of crashing
static inline int bbIDiv( int a,int b ){
	if( !b ) return 0;
	if( b==-1 ) return (int)(0u-(unsigned)a);
	return a/b;
}

static inline float bbNaN(){ return NAN; }
static inline float bbInf(){ return INFINITY; }

// userlib (.decls) argument conversions (ExprSeqNode::translate with cfunc)
static inline int bbObjFieldsPtr( BBObj *o ){ return o ? (int)(intptr_t)o->fields : 0; }
int bbBankDataPtr( int bank );

#endif
